import { Queue, Worker, Job } from 'bullmq';
import { createClient } from 'redis';

interface EmailJobData {
  emailId: string;
  recipient: string;
  template: string;
  payload: Record<string, unknown>;
}

const redisConfig = {
  host: process.env.REDIS_HOST || 'localhost',
  port: Number(process.env.REDIS_PORT) || 6379,
};

// 1. Primary Work Queue with Exponential Backoff Retry Strategy
export const emailQueue = new Queue<EmailJobData>('email-delivery', {
  connection: redisConfig,
  defaultJobOptions: {
    attempts: 5,
    backoff: {
      type: 'exponential',
      delay: 1000, // Starts at 1s, then 2s, 4s, 8s, 16s
    },
    removeOnComplete: true,
    removeOnFail: false,
  },
});

// 2. Dead-Letter Queue for permanently failed jobs
export const deadLetterQueue = new Queue<{ originalJob: EmailJobData; error: string; failedAt: string }>('email-dlq', {
  connection: redisConfig,
});

// 3. Worker Implementation
export const emailWorker = new Worker<EmailJobData>(
  'email-delivery',
  async (job: Job<EmailJobData>) => {
    console.log(`[Job ${job.id}] Processing email for ${job.data.recipient} (Attempt ${job.attemptsMade + 1}/${job.opts.attempts})`);

    // Idempotent processing logic
    await sendEmailWithProvider(job.data);
  },
  {
    connection: redisConfig,
    concurrency: 5,
  }
);

// 4. Failure Path Handler
emailWorker.on('failed', async (job: Job<EmailJobData> | undefined, err: Error) => {
  if (!job) return;

  const isFinalAttempt = job.attemptsMade >= (job.opts.attempts || 1);

  if (isFinalAttempt) {
    console.error(`[Job ${job.id}] Final attempt failed. Routing to Dead-Letter Queue. Error: ${err.message}`);

    // Push to Dead-Letter Queue for manual inspection or secondary remediation
    await deadLetterQueue.add('dlq-email-job', {
      originalJob: job.data,
      error: err.message,
      failedAt: new Date().toISOString(),
    });

    // Execute custom failure side-effects (e.g., metric reporting, user notification)
    await handlePermanentJobFailure(job.data, err);
  } else {
    console.warn(`[Job ${job.id}] Attempt ${job.attemptsMade} failed. Retrying... Error: ${err.message}`);
  }
});

