import { ClerkProvider, SignedIn, SignedOut, SignInButton, UserButton, OrganizationSwitcher } from '@clerk/nextjs';

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <ClerkProvider>
      <html lang="en">
        <body>
          <header style={{ display: 'flex', gap: '1rem', padding: '1rem', borderBottom: '1px solid #ccc' }}>
            <SignedOut>
              <SignInButton mode="modal" />
            </SignedOut>
            <SignedIn>
              <OrganizationSwitcher 
                afterCreateOrganizationUrl="/dashboard"
                afterSelectOrganizationUrl="/dashboard"
                hidePersonal={false}
              />
              <UserButton />
            </SignedIn>
          </header>
          <main>{children}</main>
        </body>
      </html>
    </ClerkProvider>
  );
}

// app/dashboard/page.tsx
import { auth } from '@clerk/nextjs/server';

export default async function DashboardPage() {
  const { userId, orgId, orgRole, orgSlug } = await auth();

  if (!orgId) {
    return (
      <div style={{ padding: '2rem' }}>
        <h2>No Active Organization</h2>
        <p>Please select or create an organization using the organization switcher in the header.</p>
      </div>
    );
  }

  return (
    <div style={{ padding: '2rem' }}>
      <h1>Organization Dashboard</h1>
      <p><strong>User ID:</strong> {userId}</p>
      <p><strong>Organization ID:</strong> {orgId}</p>
      <p><strong>Organization Slug:</strong> {orgSlug}</p>
      <p><strong>Your Role:</strong> {orgRole}</p>
    </div>
  );
}

